r=json.loads((O/'hazard_qualification_records.json').read_text());t=[x['time_s'] for x in r];axs[1].plot(t,[x['current_hazards'] for x in r],label='raw current hazards');axs[1].plot(t,[x['qualified_current_hazards'] for x in r],label='qualified current');axs[1].plot(t,[x['old_appearance_hazards'] for x in r],label='old RGB-corroborated');axs[1].set_yscale('symlog',linthresh=1);axs[1].axvline(18,color='.5',ls=':');axs[1].axvline(28,color='.5',ls=':');axs[1].set_xlabel('time [s]');axs[1].set_title('No mapped hazard evidence after 23s');axs[1].legend(fontsize=7)
